import json
evals = {}
train_steps = {}
keys_seen = set()
for line in open('metrics.jsonl'):
    d = json.loads(line)
    sk = d.get('step_key','')
    keys_seen.add(sk)
    if sk == 'eval/step':
        evals[d['step']] = {
            'acc': d['data']['eval']['countdown'],
            'trunc': d['data']['eval']['countdown/truncated_ratio'],
            'resp_len_mean': d['data']['eval']['countdown/response_len/mean'],
            'resp_len_p90': d['data']['eval']['countdown/response_len/p90'],
        }
print('step_keys:', sorted(keys_seen))
print()
for s in sorted(evals):
    e = evals[s]
    print(f\"step {s:3d}: eval_acc={e['acc']:.4f} trunc={e['trunc']:.3f} resp_len_mean={e['resp_len_mean']:.1f} p90={e['resp_len_p90']}\")
"

